'use strict';
// Information extraction: one shared rule set, immutable task snapshots, source-first review.
const ewBase={workbench,configPanel,handleAction,modalContent,closeModal,makeResult,run,validate,configurationFragment,exportRows,doExport,render};
const ewView={query:'',page:1,size:10,checked:[],closed:[],folder:null,filter:'all',resultQuery:'',resultPage:1,resultSize:10,selected:[],mobilePanel:null};
const ewStatus={running:'提取中',completed:'提取完成',partial:'部分提取失败',failed:'提取失败',stopped:'已停止',queued:'排队中'};
function ewConfig(){
 const task=currentTask(),c=task?.config||currentConfig();
 if(!task&&!c.extractionTemplateChoiceVersion){
  const initial=(tool('extract').fields||[]).map(name=>({name,description:'提取原文中的'+name+'，保留原始单位及限定条件；无法取得时标注未提取到。'}));
  // Retire only the exact legacy automatic preset, never user-selected or edited drafts.
  if(!c.extractionTemplateId&&!c.backendTemplateId&&c.template===tool('extract').template&&JSON.stringify(c.fieldDefs)===JSON.stringify(initial)&&JSON.stringify(c.fields)===JSON.stringify(tool('extract').fields)){
   c.template='';c.fieldDefs=[];c.fields=[];delete c.extractionFieldChoices;
  }
  c.extractionTemplateChoiceVersion=1;persist();
 }
 if(!task&&!c.extractionWorkflowVersion){if(+c.chunk===2000){c.chunk=12000;c.merge=false;}c.extractionWorkflowVersion=1;}
 return c;
}
function ewDocs(){return selectedDocs(currentTask()?.ids||ws().ids);}
function ewAllowed(d){return !!d&&!d.deleted&&auditFileAccess(d).analyze&&!libEligible(d,'extract');}
function ewUnavailable(d){return !d||d.deleted?'原文件已移除':!auditFileAccess(d).read?'无查看权限':!auditFileAccess(d).analyze?'无提取权限':libEligible(d,'extract')||'';}
function ewPath(d){return d.space+' / '+(folderPath(d.folder)||'根目录');}
function ewSelect(c,locked){
 const t=xtFind(c.extractionTemplateId)||xtAll().find(t=>t.name===c.template),same=t&&JSON.stringify(xtAppliedFields(t))===JSON.stringify(c.fieldDefs),hasFields=c.fieldDefs.length>0;
 const placeholder=!c.template&&!hasFields?'<option value="" selected disabled>选择模板载入字段</option>':!same?'<option value="__current__" selected>'+E(c.template?c.template+' · 本次配置':'自定义提取字段')+'</option>':'';
 return '<select aria-label="选择提取模板" data-xt-change="template" '+(locked?'disabled':'')+'>'+placeholder+['system','personal'].map(g=>'<optgroup label="'+(g==='system'?'系统模板':'个人模板')+'">'+xtAll().filter(t=>!!t.system===(g==='system')).map(t=>'<option value="'+E(t.id)+'" '+(same&&t.id===(c.extractionTemplateId||xtAll().find(x=>x.name===c.template)?.id)?'selected':'')+'>'+E(t.name)+'</option>').join('')+'</optgroup>').join('')+'</select>';
}
function ewHeader(task){const docs=ewDocs(),ready=docs.filter(ewAllowed).length;return '<header class="ew-commandbar"><div class="ew-heading"><span class="tool-symbol" style="--tool-color:'+toolColor.extract+'">'+I(tool('extract').icon)+'</span><h1>信息提取</h1></div><div class="ew-steps"><span class="'+(!docs.length?'active':'done')+'">1 选资料</span><i>›</i><span class="'+(!task&&docs.length?'active':task?'done':'')+'">2 设规则</span><i>›</i><span class="'+(task?'active':'')+'">3 核验结果</span></div><div class="ew-command-actions">'+(task?tag(ewStatus[task.status]||task.status,task.status==='completed'?'green':task.status==='partial'?'amber':'blue'):'<span class="ew-ready">可提取 <strong>'+ready+'</strong> 份</span>')+B(I('tasks','icon-sm')+'任务中心','nav-tasks','sm')+(task?task.status==='running'?B(I('pause','icon-sm')+'停止提取','stop-task','sm','data-id="'+E(task.id)+'"'):B(I('settings','icon-sm')+'本次配置','ew-config','sm')+B(I('plus','icon-sm')+'复制新建','new-analysis','sm')+B(I('download','icon-sm')+'导出','export','primary sm',task.result?.length?'':'disabled'):B(I('play','icon-sm')+'开始提取','run','primary sm',docs.length?'':'disabled'))+'</div></header>';}
function ewTree(space,path,docs,depth=0){const paths=[...new Set(docs.map(d=>folderPath(d.folder)).flatMap(p=>p.split('/').filter(Boolean).map((_,i)=>p.split('/').slice(0,i+1).join('/'))))],children=paths.filter(p=>p.split('/').slice(0,-1).join('/')===path),direct=docs.filter(d=>folderPath(d.folder)===path);return children.map(p=>{const key=space+'::'+p,closed=ewView.closed.includes(key)&&!ws().treeQuery,count=docs.filter(d=>underFolder(d.folder,p)).length;return '<div class="ew-folder" style="--depth:'+depth+'"><button class="ew-tree-toggle" data-action="ew-collapse" data-key="'+E(key)+'" aria-label="'+(closed?'展开':'收起')+E(folderName(p))+'" aria-expanded="'+!closed+'">'+I(closed?'chevron':'down','icon-sm')+'</button><button data-action="ew-folder" data-space="'+E(space)+'" data-path="'+E(p)+'" title="'+E(space+' / '+p)+'">'+I('folder','icon-sm')+'<span>'+E(folderName(p))+'</span><small title="当前显示范围内的资料数">'+count+'</small></button></div>'+(!closed?ewTree(space,p,docs,depth+1):'');}).join('')+direct.map(d=>{const task=currentTask(),failed=task?.failedIds?.includes(d.id),status=task?(task.status==='running'?'提取中':failed?'提取失败':task.successIds?.includes(d.id)?'已提取':'未提取'):ewUnavailable(d)||'解析完成';return '<div class="ew-file '+(ws().preview===d.id?'active':'')+'" style="--depth:'+depth+'">'+(manage?'<input type="checkbox" aria-label="选择移除 '+E(d.name)+'" data-ew-change="work-check" value="'+E(d.id)+'" '+(ewView.checked.includes(d.id)?'checked':'')+'>':ficon(d))+'<button class="ew-file-name" data-action="preview" data-id="'+E(d.id)+'" title="'+E(d.name)+'"><span>'+E(d.name)+'</span><small class="'+(failed?'error':'')+'">'+E(status)+'</small></button></div>';}).join('');}
function ewSidebar(){const docs=ewDocs(),q=ws().treeQuery||'',shown=docs.filter(d=>(d.name+' '+ewPath(d)).toLowerCase().includes(q.toLowerCase())),spaces=SPACE_ORDER.filter(s=>shown.some(d=>d.space===s));return '<aside class="ew-materials"><div class="ew-panel-head"><h2>本次资料 <strong>'+docs.length+'</strong></h2>'+(!currentTask()?A(manage?'完成':'管理','ew-manage'):'')+'</div><div class="ew-material-controls">'+B(I('plus','icon-sm')+'添加资料','add-tool-materials','soft w100')+'<div class="search"><span>'+I('search','icon-sm')+'</span><input id="ew-tree-query" data-ew-input="tree-query" aria-label="查找本次资料" placeholder="查找文件或目录" value="'+E(q)+'"></div></div>'+(manage?'<div class="ew-managebar"><label><input type="checkbox" data-ew-change="work-all" '+(shown.length&&shown.every(d=>ewView.checked.includes(d.id))?'checked':'')+'> 全选</label>'+A('移除 ('+ewView.checked.length+')','ew-remove-checked',ewView.checked.length?'':'disabled')+'</div>':'')+'<div class="ew-tree">'+spaces.map(s=>'<div class="ew-space">'+E(s)+'</div>'+ewTree(s,'',shown.filter(d=>d.space===s))).join('')+(!docs.length?'<div class="ew-empty-small">从资料库选择文件或文件夹，也可上传资料后添加。</div>':!shown.length?'<div class="ew-empty-small">没有匹配资料，提取范围未改变。</div>':'')+'</div><div class="ew-scope-note">'+(currentTask()?'本任务的资料快照':'全部 '+docs.length+' 份资料参与提取')+'<br><span>点击文件只切换预览</span></div></aside>';}
configPanel=function(){if(state.toolId!=='extract')return ewBase.configPanel();const c=ewConfig(),locked=!!currentTask();return '<aside class="config ew-config"><div class="ew-panel-head"><h2>'+(locked?'本次提取配置':'提取配置')+'</h2>'+tag(locked?'执行快照':'本次生效',locked?'':'blue')+'</div><div class="ew-config-body"><p class="ew-config-scope">'+(locked?'执行时的配置，只读保留。':'本次全部资料共用以下提取规则。')+'</p><section class="ew-config-section"><div class="row between"><label class="field-label" for="ew-template">提取模板</label>'+A('管理提取模板','nav-templates')+'</div>'+ewSelect(c,locked)+'<div class="ew-template-actions">'+B(I('book','icon-sm')+'存为模板','save-template','sm')+'<details class="lib-dropdown ew-more"><summary class="btn sm">更多'+I('down','icon-sm')+'</summary><div class="lib-menu">'+B(I('download','icon-sm')+'导出配置','v2-export-config','ghost')+B(I('upload','icon-sm')+'导入提取模板','ew-import','ghost',locked?'disabled':'')+(xtFind(c.extractionTemplateId)&&xtCanEdit(xtFind(c.extractionTemplateId))?B(I('trash','icon-sm')+'删除所选模板','xt-delete','ghost danger','data-id="'+E(c.extractionTemplateId)+'" '+(locked?'disabled':'')):'')+'</div></details></div></section><section class="ew-config-section"><div class="row between"><h3>提取字段 <strong>'+c.fieldDefs.length+'</strong></h3>'+A(locked?'查看字段':'编辑字段','edit-fields')+'</div><div class="ew-rules">'+c.fieldDefs.slice(0,5).map((r,i)=>'<div class="ew-rule"><span>'+(i+1)+'</span><div><b>'+E(r.name)+'</b><p title="'+E(r.description)+'">'+E(r.description||'按字段名称提取')+'</p></div></div>').join('')+'</div>'+(c.fieldDefs.length>5?A('查看全部 '+c.fieldDefs.length+' 个字段','edit-fields'):'')+'</section><section class="ew-config-section"><label class="ew-switch"><span>附件内容合并到主文件</span><input type="checkbox" role="switch" aria-label="附件内容合并到主文件" data-config="merge" '+(c.merge?'checked':'')+' '+(locked?'disabled':'')+'></label><p class="hint">'+(c.merge?'主文件与关联附件作为整体提取。':'仅提取主文件，不合并关联附件。')+'</p>'+A('管理关联附件','attachments')+'</section><details class="ew-advanced" '+(ewView.advanced?'open':'')+'><summary>高级设置</summary><div class="ew-number-grid"><label>切片字数<input aria-label="切片字数" type="number" min="1000" max="50000" step="1000" data-config="chunk" value="'+E(c.chunk)+'" '+(locked?'disabled':'')+'></label><label>冗余字数<input aria-label="冗余字数" type="number" min="0" max="5000" step="100" data-config="overlap" value="'+E(c.overlap)+'" '+(locked?'disabled':'')+'></label></div><p class="hint">切片建议10000–30000字；冗余为相邻切片重叠字数。</p>'+B('查看完整配置','v2-config-json','sm')+'</details>'+(locked?'<section class="ew-config-section"><h3>任务信息</h3><p>'+E(currentTask().name)+'</p><p class="hint">'+E(currentTask().notes||'无备注')+'</p></section>':'')+'</div></aside>';};
function ewPreparation(){const w=ws(),docs=ewDocs(),showPreview=w.tab==='preview'&&w.preview,folder=ewView.folder;let shown=docs.filter(d=>(!folder||d.space===folder.space&&underFolder(d.folder,folder.path))&&(d.name+' '+ewPath(d)).toLowerCase().includes(ewView.query.toLowerCase()));const pages=Math.max(1,Math.ceil(shown.length/ewView.size));ewView.page=Math.max(1,Math.min(ewView.page,pages));return '<section class="ew-preparation"><div class="ew-content-toolbar"><div class="ew-tabs"><button class="'+(!showPreview?'active':'')+'" data-action="ew-material-list">本次资料 <strong>'+docs.length+'</strong></button><button class="'+(showPreview?'active':'')+'" data-action="ew-preview-tab" '+(!w.preview?'disabled':'')+'>文件预览</button></div>'+(showPreview?B(I('expand','icon-sm')+'原件与解析内容','source','sm','data-id="'+E(w.preview)+'"'):B(I('paperclip','icon-sm')+'管理附件','attachments','sm',docs.length?'':'disabled'))+'</div>'+(showPreview?'<div class="ew-document"><div class="ew-file-caption"><strong title="'+E(file(w.preview)?.name)+'">'+E(file(w.preview)?.name)+'</strong><span>'+E(ewPath(file(w.preview)))+'</span></div><div class="ew-document-body">'+(auditFileAccess(file(w.preview)).preview?previewParsedMarkup(file(w.preview)):'<p class="ew-empty-small">当前没有此文件的查看权限。</p>')+'</div></div>':!docs.length?'<div class="ew-onboarding"><div class="ew-onboarding-icon">'+I(tool('extract').icon)+'</div><h2>从文档中提取所需信息</h2><p>添加审计资料，选择模板或自定义字段，提取后逐项核对原文。</p>'+B(I('plus','icon-sm')+'添加资料','add-tool-materials','primary')+'<ol><li><b>选资料</b><span>文件、文件夹及关联附件</span></li><li><b>设规则</b><span>字段名称与提取口径</span></li><li><b>看结果</b><span>汇总、核验并导出</span></li></ol></div>':'<div class="ew-list-tools"><span class="ew-directory">'+(folder?'当前目录：'+E(folder.space+' / '+folder.path):'本次提取范围')+'</span>'+(folder?A('查看全部','ew-clear-folder'):'')+'<input id="ew-material-query" data-ew-input="material-query" aria-label="搜索本次资料" placeholder="搜索文件" value="'+E(ewView.query)+'"></div><div class="ew-table-scroll"><table class="table ew-material-table"><thead><tr><th>文件名称</th><th>解析状态</th><th class="ew-location-col">位置</th><th>操作</th></tr></thead><tbody>'+pageItems(shown,ewView.page,ewView.size).map(d=>'<tr><td><div class="row">'+ficon(d)+'<button class="link ew-file-link" data-action="preview" data-id="'+E(d.id)+'">'+E(d.name)+'</button></div><div class="ew-inline-path" title="'+E(ewPath(d))+'">位置：'+E(ewPath(d))+'</div></td><td>'+libStatusTag(d)+(ewUnavailable(d)?'<span class="ew-ineligible">'+E(ewUnavailable(d))+'</span>':'')+'</td><td class="ew-location-col"><span class="ew-path" title="'+E(ewPath(d))+'">'+E(ewPath(d))+'</span></td><td><div class="row">'+A('预览','source','data-id="'+E(d.id)+'"')+A('附件'+(raAttachmentIds(d).length?' ('+raAttachmentIds(d).length+')':''),'attachments','data-id="'+E(d.id)+'"')+'</div></td></tr>').join('')+'</tbody></table>'+(!shown.length?'<div class="ew-empty-small">没有匹配资料，清除搜索或目录筛选后重试。</div>':'')+'</div>'+ewPager('materials',shown.length,ewView.page,pages,ewView.size))+'</section>';}
function ewPager(kind,count,page,pages,size){return '<div class="ew-pagination"><span>共 <strong>'+count+'</strong> '+(kind==='results'?'份结果':'份资料')+'</span><div class="row"><select aria-label="'+(kind==='results'?'结果':'资料')+'每页条数" data-ew-change="'+kind+'-size">'+[10,20,50].map(n=>'<option '+(size===n?'selected':'')+'>'+n+'</option>').join('')+'</select>'+B(I('back','icon-sm'),'ew-page','ghost sm','data-kind="'+kind+'" data-step="-1" aria-label="上一页" '+(page<=1?'disabled':''))+'<span>'+page+' / '+pages+'</span>'+B(I('chevron','icon-sm'),'ew-page','ghost sm','data-kind="'+kind+'" data-step="1" aria-label="下一页" '+(page>=pages?'disabled':''))+'</div></div>';}
function ewResultRows(task){return (task.result||[]).filter(r=>auditFileAccess(file(r.doc)).read&&(ewView.filter==='all'||ewView.filter==='missing'&&ewItems(task,r).some(f=>!f.is_found))&&JSON.stringify([file(r.doc)?.name,ewItems(task,r).map(f=>f.is_found?f.extracted:'未提取到')]).toLowerCase().includes(ewView.resultQuery.toLowerCase()));}
function ewItems(task,r){if(Array.isArray(r.items))return r.items.map(f=>f.source_id&&!auditFileAccess(file(f.source_id)).read?{...f,extracted:'',is_found:false,evidence:'',evidence_list:[],source_id:null,notes:'证据来源当前不可访问'}:f);return (task.config.fieldDefs||task.config.fields.map(name=>({name,description:''}))).map((f,i)=>({name:f.name,description:f.description,extracted:r.values?.[i]??'',is_found:!!r.values?.[i]&&r.values[i]!=='未提取到',evidence:'',confidence:null,evidence_list:[]}));}
function ewResults(task){if(ewView.taskId!==task.id){ewView.taskId=task.id;ewView.selected=[];ewView.resultPage=1;ewView.filter='all';ewView.resultQuery='';}const rows=ewResultRows(task),missing=(task.result||[]).filter(r=>ewItems(task,r).some(f=>!f.is_found)).length,pages=Math.max(1,Math.ceil(rows.length/ewView.resultSize));ewView.resultPage=Math.max(1,Math.min(ewView.resultPage,pages));const shown=pageItems(rows,ewView.resultPage,ewView.resultSize),checked=shown.length&&shown.every(r=>ewView.selected.includes(r.doc));return '<section class="ew-results"><div class="ew-result-summary"><h2>提取结果</h2><span>成功 <strong>'+task.successIds.length+'</strong> 份</span>'+(task.failedIds.length?'<span class="error">失败 <strong>'+task.failedIds.length+'</strong> 份</span>'+A('重试失败文件','retry-task'):'')+'<span>含未提取字段 <strong>'+missing+'</strong> 份</span></div><div class="ew-result-tools"><input id="ew-result-query" data-ew-input="result-query" aria-label="搜索提取结果" placeholder="搜索文件或提取值" value="'+E(ewView.resultQuery)+'"><select aria-label="结果状态" data-ew-change="result-filter"><option value="all">全部成功结果</option><option value="missing" '+(ewView.filter==='missing'?'selected':'')+'>含未提取字段</option></select><span class="grow"></span>'+A('清除筛选','ew-clear-results')+'</div>'+(ewView.selected.length?'<div class="ew-result-selection">已选 <strong>'+ewView.selected.length+'</strong> 份结果 · 跨页保留'+(checked&&rows.some(r=>!ewView.selected.includes(r.doc))?A('选择全部结果 ('+rows.length+')','ew-select-all-results'):'')+A('导出所选','ew-export-selected')+A('清空选择','ew-clear-result-selection')+'</div>':'')+'<div class="ew-table-scroll"><table class="table ew-result-table"><thead><tr><th><label class="ew-page-check"><input type="checkbox" aria-label="选择本页结果" title="只选择当前页结果" data-ew-change="result-page" '+(checked?'checked':'')+'>本页</label></th><th>来源文件</th>'+task.config.fields.map(f=>'<th>'+E(f)+'</th>').join('')+'<th>核验</th></tr></thead><tbody>'+shown.map(r=>'<tr><td><input type="checkbox" aria-label="选择结果 '+E(file(r.doc)?.name)+'" data-ew-change="result-check" value="'+E(r.doc)+'" '+(ewView.selected.includes(r.doc)?'checked':'')+'></td><td><button class="link ew-file-link" data-action="ew-review" data-id="'+E(r.doc)+'">'+E(file(r.doc)?.name||r.doc)+'</button></td>'+ewItems(task,r).map((f,i)=>'<td><button class="ew-value '+(!f.is_found?'ew-missing':'')+'" data-action="ew-review" data-id="'+E(r.doc)+'" data-index="'+i+'">'+E(f.is_found?f.extracted:'未提取到')+'</button></td>').join('')+'<td>'+A('查看原文','ew-review','data-id="'+E(r.doc)+'"')+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="ew-empty-small">没有匹配的结果。'+A('清除筛选','ew-clear-results')+'</div>':'')+'</div><div class="ew-result-note">“未提取到”仅表示本次未取得该字段值，不代表原文未涉及。点击提取值核对来源。</div>'+ewPager('results',rows.length,ewView.resultPage,pages,ewView.resultSize)+'</section>';}
function ewProgress(task){const done=task.progress>=65?Math.max(0,Math.floor(task.ids.length*(task.progress-45)/55)):0;return '<section class="ew-progress"><div class="ew-progress-head"><span class="ew-progress-symbol">'+I('clock')+'</span><div><h2>'+E(task.phase.replaceAll('分析','提取'))+'</h2><p>'+E(task.name)+'</p></div><strong>'+task.progress+'%</strong></div><div class="progress-track"><i style="width:'+task.progress+'%"></i></div><div class="ew-progress-meta">共 <strong>'+task.ids.length+'</strong> 份 · 已处理 <strong>'+done+'</strong> 份<span>离开页面后可在任务中心查看</span></div><div class="ew-table-scroll"><table class="table"><thead><tr><th>文件名称</th><th>提取进度</th></tr></thead><tbody>'+task.ids.map((id,i)=>'<tr><td>'+E(file(id)?.name||id)+'</td><td>'+tag(i<done?'提取完成':task.progress<30?'等待提取':'提取中',i<done?'green':'blue')+'</td></tr>').join('')+'</tbody></table></div></section>';}
function ewTaskArea(task){if(task.status==='running')return ewProgress(task);if(['stopped','failed'].includes(task.status))return '<section class="ew-failed"><span class="ew-progress-symbol">'+I(task.status==='failed'?'warning':'pause')+'</span><h2>'+ewStatus[task.status]+'</h2><p>已保留 '+task.ids.length+' 份资料与本次配置。'+(task.status==='failed'?'提取服务未返回有效结果，可重试失败文件。':'可复制配置后重新提取。')+'</p>'+B(task.status==='failed'?'重试失败文件':'复制配置新建',task.status==='failed'?'retry-task':'new-analysis','primary')+'</section>';return ewResults(task);}
workbench=function(){if(state.toolId!=='extract')return ewBase.workbench();const task=currentTask();ewConfig();return '<div class="ew-workspace">'+ewHeader(task)+'<div class="ew-grid '+(task&&!configExpanded?'ew-without-config':'')+'">'+ewSidebar()+'<main class="ew-center">'+(task?ewTaskArea(task):ewPreparation())+'</main>'+(!task||configExpanded?configPanel():'')+'</div></div>';};
// Original buildExecConfigBySettings uses overlap (not chunk_overlap).
function ewExecConfig(c){const extra={merge_attachments:!!c.merge,chunk_size:+c.chunk,overlap:+c.overlap};return c.backendTemplateId&&c.backendTemplateFields===JSON.stringify(c.fieldDefs)?{exec_mode:'template',template_id:String(c.backendTemplateId),custom_config:extra}:{exec_mode:'custom',custom_config:{mode:'field',fields:c.fieldDefs.map(f=>({name:f.name,description:f.description||''})),...extra}};}
function ewExecutionPayload(task){return {task_name:task.name,tool_name:'非结构化信息提取',task_notes:task.notes||'',task_switch:task.executionMode||1,biz_type:'fileToPdf',files:task.ids.map(id=>({file_id:String(file(id)?.file_id||file(id)?.fileId||id),...ewExecConfig(task.config)})),parse_status:['parsed'],file_extensions:[],deleted_files:[]};}
configurationFragment=function(id,c){return id==='extract'?ewExecConfig(c):ewBase.configurationFragment(id,c);};
validate=function(show=true){if(state.toolId!=='extract')return ewBase.validate(show);const w=ws(),c=ewConfig(),errors=[];if(!w.ids.length)errors.push('请先添加需要提取的资料');w.ids.forEach(id=>{const reason=ewUnavailable(file(id));if(reason)errors.push((file(id)?.name||id)+'：'+reason);});if(!c.fieldDefs.length)errors.push('请至少添加一个提取字段');if(c.fieldDefs.length>200)errors.push('提取字段不能超过200个');if(c.fieldDefs.some(f=>!f.name?.trim()))errors.push('请填写字段名称');if(new Set(c.fieldDefs.map(f=>f.name.trim())).size!==c.fieldDefs.length)errors.push('字段名称不能重复');if(!Number.isInteger(+c.chunk)||+c.chunk<1000||+c.chunk>50000)errors.push('切片字数应为1000–50000的整数');if(!Number.isInteger(+c.overlap)||+c.overlap<0||+c.overlap>5000||+c.overlap>=+c.chunk)errors.push('冗余字数应为0–5000的整数，且小于切片字数');if(show&&errors.length)openModal('validation',{errors:[...new Set(errors)]});return [...new Set(errors)];};
// Local extraction only returns strings actually present in the selected text, with their source line.
function ewLocalField(d,f,task){const sources=[d,...(task.config.merge?selectedDocs(task.attachments[d.id]||[]):[])].filter(x=>auditFileAccess(x).read),name=f.name,kind=['金额与单位','合同金额','批准金额','投资金额','发票金额','价税合计'].includes(name)?'amount':['关键日期','合同签订日期','批准日期','开票时间','会议时间'].includes(name)?'date':['涉及单位','涉及主体'].includes(name)?'unit':['文件主题','文件名称','文件标题','合同名称','会议名称'].includes(name)?'title':null;let found=null;for(const src of sources){const text=(AUDIT_SOURCE_ASSETS[src.id]&&src.title?src.title+'\n':'')+previewText(src),lines=text.split(/\n/).map(l=>l.trim()).filter(Boolean);let value='';if(kind==='amount'&&(name!=='发票金额'&&name!=='价税合计'||/发票|开票/.test(text)))value=text.match(/(?:人民币)?\s*[\d,，]+(?:\.\d+)?\s*(?:亿元|万元|元)/)?.[0]?.trim()||'';if(kind==='date'&&(name!=='合同签订日期'||/合同/.test(src.title||''))&&(name!=='批准日期'||/批复|批准/.test(src.title||''))&&(name!=='开票时间'||/发票|开票/.test(text))&&(name!=='会议时间'||/会议|纪要/.test(src.title||'')))value=text.match(/20\d{2}[年\-/]\d{1,2}[月\-/]\d{1,2}日?/)?.[0]||'';if(kind==='title'&&(name!=='合同名称'||/合同/.test(src.title||''))&&(name!=='会议名称'||/会议|纪要/.test(src.title||''))){const title=src.title||src.name.replace(/\.[^.]+$/,'');value=text.includes(title)?title:lines.find(l=>l.length<=100&&!/[。；]/.test(l))||'';}if(kind==='unit'){const units=(src.unit||'').split(/[/、，,]/).map(x=>x.trim()).filter(x=>x&&x!=='未提取到'&&text.includes(x));value=units.join(' / ');if(!value)value=text.match(/[\u4e00-\u9fa5]{2,24}(?:有限公司|建设中心|审计局|管理局)/)?.[0]||'';}if(!kind){const line=lines.find(l=>l.includes(name)&&/[:：]/.test(l));if(line)value=line.slice(line.indexOf(/：/.test(line)?'：':':')+1).trim();}if(value){const evidence=lines.find(l=>l.includes(value)||kind==='unit'&&value.split(' / ').some(v=>l.includes(v)))||'';if(evidence){found={name,description:f.description||'',extracted:value,is_found:true,evidence,source_id:src.id,evidence_list:[{text:evidence,source_file_id:src.id}],confidence:null};break;}}}return found||{name,description:f.description||'',extracted:'',is_found:false,evidence:'',evidence_list:[],confidence:null};}
makeResult=function(task){if(task.toolId!=='extract')return ewBase.makeResult(task);return selectedDocs(task.successIds||task.ids).map(d=>{if(task.nativeResults?.[d.id])return ewNormalizeResult(task.nativeResults[d.id],d.id,task.config);const items=task.config.fieldDefs.map(f=>ewLocalField(d,f,task));return {doc:d.id,title:d.title||d.name,items,values:items.map(f=>f.is_found?f.extracted:'未提取到')};});};
run=function(retry){if(state.toolId!=='extract')return ewBase.run(retry);if(!retry&&validate().length)return;if(retry&&retry.ids.some(id=>!ewAllowed(file(id))))return toast('部分资料不可提取，请核对解析状态和访问权限。');ewView.resultPage=1;ewView.selected=[];ewBase.run(retry);const task=currentTask();if(task){task.configFragment=ewExecConfig(task.config);task.executionMode=task.config.executionMode||1;persist();}};
function ewFieldEditor(p){const locked=!!currentTask(),fields=p.fields;return modalFrame(locked?'本次提取字段':'编辑提取字段','字段名称为必填项；提取说明用于明确取值口径、范围和输出要求。','<div class="ew-fields-toolbar"><strong>共 '+fields.length+' 个字段</strong>'+(!locked?'<select aria-label="从模板追加字段" id="ew-load-template"><option value="">从模板追加字段</option>'+xtAll().map(t=>'<option value="'+E(t.id)+'">'+E(t.name)+'</option>').join('')+'</select>'+B('加载','ew-load-fields','sm')+B(I('plus','icon-sm')+'添加字段','ew-add-field','soft sm'):'')+'</div><div class="ew-field-table-scroll"><table class="table ew-field-table"><thead><tr><th>序号</th><th>字段名称 <b class="red">*</b></th><th>提取说明</th><th>操作</th></tr></thead><tbody>'+fields.map((f,i)=>'<tr><td>'+(i+1)+'</td><td><input id="ew-field-'+i+'" aria-label="字段'+(i+1)+'名称" data-ew-field="name" data-index="'+i+'" value="'+E(f.name)+'" placeholder="输入字段名称" '+(locked?'readonly':'')+'></td><td><textarea aria-label="字段'+(i+1)+'提取说明" data-ew-field="description" data-index="'+i+'" rows="2" placeholder="可选，留空时按字段名称提取" '+(locked?'readonly':'')+'>'+E(f.description)+'</textarea></td><td>'+(!locked?'<div class="row">'+B('↑','ew-field-up','ghost sm','data-index="'+i+'" aria-label="上移字段'+(i+1)+'" '+(!i?'disabled':''))+B('↓','ew-field-down','ghost sm','data-index="'+i+'" aria-label="下移字段'+(i+1)+'" '+(i===fields.length-1?'disabled':''))+B(I('trash','icon-sm'),'ew-delete-field','ghost danger sm','data-index="'+i+'" aria-label="删除字段'+(i+1)+'"')+'</div>':'—')+'</td></tr>').join('')+'</tbody></table></div><p class="error" id="ew-field-error" role="alert">'+E(p.error||'')+'</p>','<span class="ew-footer-note">仅更新本次提取配置，原模板保留。</span><div class="row">'+B(locked?'关闭':'取消','close-modal')+(!locked?B('应用字段','ew-save-fields','primary'):'')+'</div>','ew-fields-dialog');}
function ewDisplay(v){return v==null?'':typeof v==='object'?JSON.stringify(v):String(v);}
function ewNormalizeResult(raw,docId,config){let data=raw;try{if(typeof data==='string')data=JSON.parse(data);if(data?.disposal_result_parsed||data?.disposal_result){data=data.disposal_result_parsed||data.disposal_result;if(typeof data==='string')data=JSON.parse(data);}}catch{return {doc:docId,items:[],values:[],invalid:true};}const joint=data?.joint_table;if(joint?.columns&&joint?.rows){const row=joint.rows.find(r=>(r.fileName||r.file_name)===file(docId)?.name);if(!row)return {doc:docId,items:[],values:[],unmatched:true};const fields=joint.columns.filter(c=>!['文件名','fileName','来源文件'].includes(c)).map(name=>({name,extracted:ewDisplay(row.values?.[name]),is_found:row.values?.[name]!=null,evidence:'',confidence:null,description:''}));return {doc:docId,items:fields,values:fields.map(f=>f.is_found?f.extracted:'未提取到')};}const list=data?.final_result?.items||data?.items||[];const items=(Array.isArray(list)?list:[]).map((f,i)=>{const extracted=ewDisplay(f.extracted!==undefined?f.extracted:f.value!==undefined?f.value:f.fieldValue),evidenceList=Array.isArray(f.evidence_list)?f.evidence_list:[],evidence=ewDisplay(f.evidence)||evidenceList.map(x=>ewDisplay(typeof x==='string'?x:x.text||x.evidence||'')).filter(Boolean).join('\n');return {name:f.name||f.fieldName||config.fieldDefs?.[i]?.name||'字段'+(i+1),description:f.description||f.fieldDescription||'',extracted,is_found:![false,'False','false',0].includes(f.is_found??f.isFound)&&extracted!=='',evidence,evidence_list:evidenceList,source_id:f.source_file_id||f.source_id||docId,confidence:typeof f.confidence==='number'&&Number.isFinite(f.confidence)?f.confidence:null,chunk_id:f.chunk_id||'',notes:f.notes||''};});return {doc:docId,items,values:items.map(f=>f.is_found?f.extracted:'未提取到')};}
function ewReviewMarkup(task,id,index=0){const r=task.result.find(r=>r.doc===id),fields=r?ewItems(task,r):[];return '<div class="ew-review-count">提取字段 <strong>'+fields.length+'</strong> · 已取值 <strong>'+fields.filter(f=>f.is_found).length+'</strong></div><div class="ew-review-fields">'+fields.map((f,i)=>'<article class="ew-review-field '+(i===index?'active':'')+'" id="ew-review-field-'+i+'"><div class="row between"><h3>'+E(f.name)+'</h3>'+tag(f.is_found?'已提取':'未提取到',f.is_found?'green':'amber')+'</div><div class="ew-review-value">'+E(f.is_found?f.extracted:'本次未取得该字段值')+'</div>'+(f.description?'<p class="ew-review-rule">提取口径：'+E(f.description)+'</p>':'')+(f.evidence?'<div class="ew-evidence"><label>原文证据'+(f.source_id&&f.source_id!==id?' · 来自附件':'')+'</label><blockquote>'+E(f.evidence)+'</blockquote><div class="row">'+A('定位解析内容','ew-locate','data-index="'+i+'"')+(f.source_id&&f.source_id!==id?A('查看附件原件','source','data-id="'+E(f.source_id)+'"'):'')+'</div></div>':'<p class="hint">'+(f.is_found?'当前结果未提供定位证据，可切换解析内容核对。':'请核对原文、字段口径和附件范围。')+'</p>')+(Number.isFinite(f.confidence)?'<p class="hint">模型置信度 '+f.confidence+'%（不代表审计确认）</p>':'')+'</article>').join('')+'</div>';}
modalContent=function(){const p=modalData;if(modal==='attachments'&&state.view==='tool'&&state.toolId==='extract'){const d=file(p.id||ws().preview||ewDocs()[0]?.id),task=currentTask();if(!d)return modalFrame('关联附件','','<p>请先添加并选择一份主文件。</p>',B('关闭','close-modal'),'small');const ids=raAttachmentIds(d,task),docs=selectedDocs(ids).filter(a=>auditFileAccess(a).read),editable=!task&&(typeof efCanLink==='function'?efCanLink(d):auditFileAccess(d).attachments);return modalFrame('关联附件',E(d.name),(task?'<p class="hint">本次执行时的附件快照，只读保留。</p>':'<div class="ef-attachment-option"><label class="ew-switch"><span>提取时包含附件内容</span><input type="checkbox" role="switch" aria-label="提取时包含附件内容" data-ef-change="attachment-merge" '+(ws().config.merge?'checked':'')+'></label><p class="hint">'+(ws().config.merge?'已开启：本次全部资料均合并各自附件提取。':'未开启：本次只提取主文件，关联附件暂不参与提取。')+'解除关联不删除原文件。</p></div>')+'<div class="ew-attachments-table">'+(docs.length?simpleTable(['附件名称','位置','操作'],docs.map(a=>[E(a.name),E(ewPath(a)),A('查看原文','source','data-id="'+E(a.id)+'"')+(editable?' '+A('移除关联','unlink-attachment','data-main="'+E(d.id)+'" data-id="'+E(a.id)+'"'):'')]),true):'<div class="ew-empty-small">暂无可查看的关联附件。</div>')+'</div>',B('关闭','close-modal')+(editable?B(I('plus','icon-sm')+'关联已有资料','pick-attachment','primary','data-id="'+E(d.id)+'"'):''),'medium');}if(modal==='ew-fields')return ewFieldEditor(p);if(modal==='ew-discard')return modalFrame('放弃字段修改？','','<p>当前修改尚未应用到本次提取。</p>',B('继续编辑','ew-continue')+B('放弃修改','ew-discard','danger'),'small');if(modal==='ew-submit'){const c=ws().config;return modalFrame('开始信息提取','全部 '+ws().ids.length+' 份资料使用同一套提取规则。','<div class="ew-submit-summary"><span>资料 <strong>'+ws().ids.length+'</strong> 份</span><span>字段 <strong>'+c.fieldDefs.length+'</strong> 个</span><span>合并附件 <strong>'+(c.merge?'是':'否')+'</strong></span></div><label class="field"><span>任务名称 <b class="red">*</b></span><input id="ew-task-name" data-ew-submit="name" maxlength="100" value="'+E(p.name)+'"></label><label class="field"><span>任务备注 <span class="muted">（选填）</span></span><textarea id="ew-task-notes" data-ew-submit="notes" rows="2" placeholder="记录本次提取目的或审计关注">'+E(p.notes)+'</textarea></label><label class="field"><span>执行方式</span><select id="ew-execution" data-ew-submit="execution"><option value="1">立即执行 · 在当前页面查看进度</option><option value="2" '+(+p.execution===2?'selected':'')+'>提交后台 · 前往任务中心跟踪</option></select></label><p class="hint">执行后保留资料与配置快照，后续修改不影响本次任务。</p><p id="ew-submit-error" class="error" role="alert"></p>',B('取消','close-modal')+B(I('play','icon-sm')+'确认提取','ew-submit-confirm','primary'),'ew-submit-dialog');}
if(modal==='ew-export'){const task=currentTask(),can=ewExportable(task),selected=p.scope==='selected',count=selected?ewView.selected.filter(id=>can.some(r=>r.doc===id)).length:can.length;return modalFrame('导出提取结果','保留来源、提取值与本次配置；证据明细随文件导出。','<label class="field"><span>导出范围</span><select id="ew-export-scope"><option value="all" '+(!selected?'selected':'')+'>任务全部可访问结果 ('+can.length+' 份)</option><option value="selected" '+(selected?'selected':'')+' '+(!ewView.selected.length?'disabled':'')+'>所选结果 ('+ewView.selected.length+' 份)</option>'+can.map(r=>'<option value="'+E(r.doc)+'">'+E(file(r.doc)?.name)+'</option>').join('')+'</select></label><label class="field"><span>文件格式</span><select id="ew-export-format"><option value="xlsx">Excel · 汇总、字段证据、任务配置</option><option value="csv">CSV · 字段及证据明细</option><option value="markdown">Markdown · 字段与原文证据</option><option value="json">JSON · 完整结果与配置</option></select></label><p class="hint">当前可导出 '+count+' 份资料。屏幕搜索条件不改变“任务全部结果”的范围。</p>',B('取消','close-modal')+B(I('download','icon-sm')+'导出文件','do-export','primary',count?'':'disabled'),'small');}
let html=ewBase.modalContent();if(modal==='source'&&p.extractionTaskId&&auditFileAccess(file(p.id)).preview){const task=state.tasks.find(t=>t.id===p.extractionTaskId);if(task){const node=document.createElement('div');node.innerHTML=html;const right=node.querySelectorAll('.file-preview-pane')[1];if(right){right.classList.add('ew-review-pane');right.querySelector('.file-preview-pane-head').innerHTML='<div class="ew-tabs"><button class="active" data-action="ew-review-tab" data-tab="fields">提取结果</button><button data-action="ew-review-tab" data-tab="parsed">解析内容</button></div>';const parsed=right.querySelector('#preview-parsed-content');parsed.hidden=true;parsed.insertAdjacentHTML('beforebegin','<div id="ew-review-content" class="file-preview-pane-content">'+ewReviewMarkup(task,p.id,p.fieldIndex||0)+'</div>');}node.querySelector('.preview-footer-note').textContent='左侧核对原始文件，右侧查看提取字段与证据。';const foot=node.querySelector('.modalfoot .row');foot?.insertAdjacentHTML('afterbegin',B('上一份','ew-review-prev','sm',task.successIds.indexOf(p.id)<=0?'disabled':'')+B('下一份','ew-review-next','sm',task.successIds.indexOf(p.id)>=task.successIds.length-1?'disabled':''));html=node.innerHTML;requestAnimationFrame(()=>document.getElementById('ew-review-field-'+(p.fieldIndex||0))?.scrollIntoView({block:'nearest'}));}}return html;};
exportRows=function(task,scope='all'){if(task.toolId!=='extract')return ewBase.exportRows(task,scope);const rows=ewExportable(task).filter(r=>scope==='all'||r.doc===scope);return [['来源文件','位置',...task.config.fields],...rows.map(r=>[file(r.doc).name,ewPath(file(r.doc)),...ewItems(task,r).map(f=>f.is_found?f.extracted:'未提取到')])];};
function ewExportable(task){return (task.result||[]).filter(r=>auditFileAccess(file(r.doc)).download&&auditFileAccess(file(r.doc)).read);}
function ewExport(){const task=currentTask();if(!task||task.toolId!=='extract')return;const scope=$('#ew-export-scope').value,format=$('#ew-export-format').value,rows=ewExportable(task).filter(r=>scope==='all'||scope==='selected'&&ewView.selected.includes(r.doc)||r.doc===scope);if(!rows.length)return toast('当前范围没有可导出的结果，或下载权限已变化。');const detail=[['来源文件','文件位置','字段名称','提取值','提取状态','提取口径','原文证据','证据来源文件'],...rows.flatMap(r=>ewItems(task,r).map(f=>[file(r.doc).name,ewPath(file(r.doc)),f.name,f.extracted,f.is_found?'已提取':'未提取到',f.description||'',f.evidence||'',file(f.source_id)?.name||'']))],summary=[['来源文件','位置',...task.config.fields],...rows.map(r=>[file(r.doc).name,ewPath(file(r.doc)),...ewItems(task,r).map(f=>f.is_found?f.extracted:'未提取到')])],name=task.name.replace(/[\\/:*?"<>|]/g,'-');if(format==='xlsx'){const wb=XLSX.utils.book_new();for(const [sheet,data] of [['提取汇总',summary],['字段证据',detail],['任务配置',[['任务名称',task.name],['任务备注',task.notes||''],['字段规则',JSON.stringify(task.config.fieldDefs)],['执行参数',JSON.stringify(ewExecConfig(task.config))]]]])XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(data),sheet);XLSX.writeFile(wb,name+'.xlsx');}else if(format==='csv')download(name+'.csv','\uFEFF'+detail.map(row=>row.map(v=>csvCell(typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v)).join(',')).join('\r\n'),'text/csv;charset=utf-8');else if(format==='markdown'){const cell=v=>String(v??'').replaceAll('|','\\|').replaceAll('\n','<br>');download(name+'.md','# '+task.name+'\n\n'+[detail[0],detail[0].map(()=>'---'),...detail.slice(1)].map(r=>'| '+r.map(cell).join(' | ')+' |').join('\n'),'text/markdown;charset=utf-8');}else download(name+'.json',JSON.stringify({task:task.name,notes:task.notes,config:task.config,exec_config:ewExecConfig(task.config),results:rows.map(r=>({doc:r.doc,source_name:file(r.doc).name,source_path:ewPath(file(r.doc)),items:ewItems(task,r),values:ewItems(task,r).map(f=>f.is_found?f.extracted:'未提取到')}))},null,2),'application/json;charset=utf-8');ewBase.closeModal();}
function ewPaintFields(focus){const scroll=$('.ew-field-table-scroll')?.scrollTop||0;paintModal();const area=$('.ew-field-table-scroll');if(area)area.scrollTop=scroll;if(focus)document.getElementById(focus)?.focus();}
handleAction=function(action,el){const id=el?.dataset?.id,index=+el?.dataset?.index;const extraction=state.view==='tool'&&state.toolId==='extract';if(extraction&&action==='run'){if(validate().length)return;const c=ws().config;openModal('ew-submit',{name:c.taskName||'信息提取 · '+new Date().toLocaleString('zh-CN',{hour12:false}),notes:c.taskNotes||'',execution:1});return;}if(extraction&&action==='edit-fields'){const fields=structuredClone(ewConfig().fieldDefs);openModal('ew-fields',{fields,initial:JSON.stringify(fields)});return;}if(extraction&&['export','ew-export-selected'].includes(action)){openModal('ew-export',{scope:action==='export'?'all':'selected'});return;}if(modal==='ew-export'&&action==='do-export')return ewExport();if(!action.startsWith('ew-'))return ewBase.handleAction(action,el);
switch(action){
case 'ew-config':configExpanded=!configExpanded;render();break;
case 'ew-manage':manage=!manage;ewView.checked=[];render();break;
case 'ew-remove-checked':{if(currentTask())return;const w=ws(),old=[...w.ids],remove=new Set(ewView.checked);w.ids=w.ids.filter(id=>!remove.has(id));if(!w.ids.includes(w.preview))w.preview=w.ids[0]||null;ewView.checked=[];manage=false;render();toast('已移出本次提取，原文件保留。',()=>{w.ids=old;render();});break;}
case 'ew-collapse':{const key=el.dataset.key;ewView.closed=ewView.closed.includes(key)?ewView.closed.filter(k=>k!==key):[...ewView.closed,key];render();break;}
case 'ew-folder':if(currentTask()){toast('提取结果按文件展示，可在左侧点击文件核验。');break;}ewView.folder={space:el.dataset.space,path:el.dataset.path};ws().tab='materials';ewView.page=1;render();break;
case 'ew-material-list':ws().tab='materials';render();break;
case 'ew-clear-folder':ewView.folder=null;ewView.page=1;render();break;
case 'ew-preview-tab':ws().tab='preview';render();break;
case 'ew-page':if(el.dataset.kind==='results')ewView.resultPage+=+el.dataset.step;else ewView.page+=+el.dataset.step;render();break;
case 'ew-clear-results':ewView.filter='all';ewView.resultQuery='';ewView.resultPage=1;render();break;
case 'ew-select-all-results':ewView.selected=[...new Set([...ewView.selected,...ewResultRows(currentTask()).map(r=>r.doc)])];render();break;
case 'ew-clear-result-selection':ewView.selected=[];render();break;
case 'ew-submit-confirm':{if(modal!=='ew-submit'||currentTask())return;const name=modalData.name.trim();if(!name){$('#ew-submit-error').textContent='请填写任务名称';return;}if(validate(false).length){$('#ew-submit-error').textContent=validate(false).join('；');return;}const p=structuredClone(modalData),c=ws().config;c.taskName=name;c.taskNotes=p.notes;c.executionMode=+p.execution;c.fields=c.fieldDefs.map(f=>f.name);ewBase.closeModal();run();if(+p.execution===2)nav('tasks');break;}
case 'ew-add-field':if(currentTask())return;if(modalData.fields.length>=200){$('#ew-field-error').textContent='最多添加200个字段';return;}modalData.fields.push({name:'',description:''});ewPaintFields('ew-field-'+(modalData.fields.length-1));break;
case 'ew-delete-field':if(!currentTask()){modalData.fields.splice(index,1);ewPaintFields();}break;
case 'ew-field-up':case 'ew-field-down':{if(currentTask())return;const to=index+(action==='ew-field-up'?-1:1),fields=modalData.fields;if(to<0||to>=fields.length)return;[fields[index],fields[to]]=[fields[to],fields[index]];ewPaintFields('ew-field-'+to);break;}
case 'ew-load-fields':{if(currentTask())return;const t=xtFind($('#ew-load-template').value);if(!t)return;const names=new Set(modalData.fields.map(f=>f.name)),add=xtFields(t).filter(f=>!names.has(f.name));if(modalData.fields.length+add.length>200)return toast('追加后不能超过200个字段。');modalData.fields.push(...structuredClone(add));ewPaintFields();toast('已追加 '+add.length+' 个字段，同名字段保留原配置。');break;}
case 'ew-save-fields':{if(currentTask())return;const fields=modalData.fields.map(f=>({name:f.name.trim(),description:f.description.trim()}));let error=!fields.length?'请至少添加一个提取字段':fields.some(f=>!f.name)?'请填写字段名称':new Set(fields.map(f=>f.name)).size!==fields.length?'字段名称不能重复':'';if(error){$('#ew-field-error').textContent=error;return;}const c=ws().config;c.fieldDefs=fields;c.fields=fields.map(f=>f.name);delete c.backendTemplateId;ewBase.closeModal();render();toast('字段已应用到本次全部资料，原模板保留。');break;}
case 'ew-continue':openModal('ew-fields',modalData.back);break;
case 'ew-discard':ewBase.closeModal();break;
case 'ew-import':openModal('xt-import');break;
case 'ew-review':{const task=currentTask();if(!task?.result?.some(r=>r.doc===id)||!auditFileAccess(file(id)).preview)return toast('当前没有此文件的核验权限。');previewRelease();openModal('source',{id,extractionTaskId:task.id,fieldIndex:Number.isInteger(index)?index:0});break;}
case 'ew-review-prev':case 'ew-review-next':{const task=state.tasks.find(t=>t.id===modalData.extractionTaskId),ids=task.successIds.filter(id=>auditFileAccess(file(id)).preview),i=ids.indexOf(modalData.id)+(action==='ew-review-prev'?-1:1);if(!ids[i])return;const taskId=task.id;previewRelease();openModal('source',{id:ids[i],extractionTaskId:taskId,fieldIndex:0});break;}
case 'ew-review-tab':{const fields=el.dataset.tab==='fields';$('#ew-review-content').hidden=!fields;$('#preview-parsed-content').hidden=fields;$$('.ew-review-pane .ew-tabs button').forEach(b=>b.classList.toggle('active',(b.dataset.tab==='fields')===fields));break;}
case 'ew-locate':{const task=state.tasks.find(t=>t.id===modalData.extractionTaskId),r=task.result.find(r=>r.doc===modalData.id),f=ewItems(task,r)[index];if(!f?.evidence)return;if(f.source_id&&f.source_id!==modalData.id){toast('证据来自关联附件，请点击“查看附件原件”核对。');return;}$('#ew-review-content').hidden=true;const body=$('#preview-parsed-content');body.hidden=false;$$('.ew-review-pane .ew-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab==='parsed'));const d=file(modalData.id),text=(AUDIT_SOURCE_ASSETS[d.id]&&d.title?d.title+'\n':'')+previewText(d),at=text.indexOf(f.evidence);body.innerHTML='<article class="preview-parsed-markdown"><pre class="ew-located-text">'+(at>=0?E(text.slice(0,at))+'<mark id="ew-evidence-mark">'+E(f.evidence)+'</mark>'+E(text.slice(at+f.evidence.length)):E(text))+'</pre></article>';$('#ew-evidence-mark')?.scrollIntoView({block:'center'});if(at<0)toast('当前解析文本中未找到完全一致的证据，请手动核对原件。');break;}
}
};
closeModal=function(){if(modal==='source'&&ewPreviewReturns.length){const back=ewPreviewReturns.pop();previewRelease();openModal(back.type,back.data);return;}if(modal==='ew-fields'&&!currentTask()&&JSON.stringify(modalData.fields)!==modalData.initial){openModal('ew-discard',{back:structuredClone(modalData)});return;}return ewBase.closeModal();};
// File clicks in the task keep the result view and open original + extracted fields.
const ewFileAction=handleAction,ewLocked=isLocked;
const ewPreviewReturns=[];
isLocked=function(){return state.toolId==='extract'&&currentTask()?true:ewLocked();};
handleAction=function(action,el){if(state.view==='tool'&&state.toolId==='extract'&&['unlink-attachment','pick-attachment'].includes(action)&&currentTask())return toast('历史任务附件只读，请通过“再次分析”修改。');if(action==='source'&&state.view==='tool'&&state.toolId==='extract'&&(modal==='attachments'||modal==='source'&&modalData.extractionTaskId)){ewPreviewReturns.push({type:modal,data:structuredClone(modalData)});}if(state.view==='tool'&&state.toolId==='extract'&&action==='preview'&&currentTask()){const task=currentTask();if(task.result?.some(r=>r.doc===el.dataset.id))return ewFileAction('ew-review',el);return toast(task.failedIds?.includes(el.dataset.id)?'此文件提取失败，可重试失败文件。':'文件尚未生成提取结果。');}if(state.view==='tool'&&state.toolId==='extract'&&action==='preview'&&!currentTask()){ws().preview=el.dataset.id;ws().tab='preview';render();return ewFileAction('source',el);}return ewFileAction(action,el);};
window.addEventListener('input',e=>{const el=e.target;if(el.dataset.ewField&&modal==='ew-fields'&&!currentTask()){modalData.fields[+el.dataset.index][el.dataset.ewField]=el.value;return;}if(el.dataset.ewSubmit&&modal==='ew-submit'){modalData[el.dataset.ewSubmit]=el.value;return;}const k=el.dataset.ewInput;if(!k)return;const pos=el.selectionStart,id=el.id;if(k==='tree-query')ws().treeQuery=el.value;if(k==='material-query'){ewView.query=el.value;ewView.page=1;}if(k==='result-query'){ewView.resultQuery=el.value;ewView.resultPage=1;}render();const next=document.getElementById(id);next?.focus();next?.setSelectionRange(pos,pos);},true);
window.addEventListener('change',e=>{const el=e.target,k=el.dataset.ewChange;if(el.dataset.ewSubmit&&modal==='ew-submit')modalData[el.dataset.ewSubmit]=el.value;if(!k)return;e.stopImmediatePropagation();if(k==='work-check')ewView.checked=el.checked?[...new Set([...ewView.checked,el.value])]:ewView.checked.filter(id=>id!==el.value);if(k==='work-all'){const q=(ws().treeQuery||'').toLowerCase(),ids=ewDocs().filter(d=>(d.name+' '+ewPath(d)).toLowerCase().includes(q)).map(d=>d.id);ewView.checked=el.checked?[...new Set([...ewView.checked,...ids])]:ewView.checked.filter(id=>!ids.includes(id));}if(k==='result-filter'){ewView.filter=el.value;ewView.resultPage=1;}if(k==='materials-size'){ewView.size=+el.value;ewView.page=1;}if(k==='results-size'){ewView.resultSize=+el.value;ewView.resultPage=1;}if(k==='result-check')ewView.selected=el.checked?[...new Set([...ewView.selected,el.value])]:ewView.selected.filter(id=>id!==el.value);if(k==='result-page'){const ids=pageItems(ewResultRows(currentTask()),ewView.resultPage,ewView.resultSize).map(r=>r.doc);ewView.selected=el.checked?[...new Set([...ewView.selected,...ids])]:ewView.selected.filter(id=>!ids.includes(id));}render();},true);
document.addEventListener('toggle',e=>{if(e.target.matches('.ew-advanced'))ewView.advanced=e.target.open;},true);
document.addEventListener('click',e=>{document.querySelectorAll('.ew-more[open]').forEach(d=>{if(!d.contains(e.target)||e.target.closest('[data-action]'))d.open=false;});},true);
render=function(){ewBase.render();if(state.view!=='tool'||state.toolId!=='extract')return;const task=currentTask(),check=$('[data-ew-change="result-page"]');if(task&&check){const rows=pageItems(ewResultRows(task),ewView.resultPage,ewView.resultSize),count=rows.filter(r=>ewView.selected.includes(r.doc)).length;check.indeterminate=count>0&&count<rows.length;check.setAttribute('aria-checked',check.indeterminate?'mixed':String(check.checked));}const workCheck=$('[data-ew-change="work-all"]');if(workCheck){const q=(ws().treeQuery||'').toLowerCase(),ids=ewDocs().filter(d=>(d.name+' '+ewPath(d)).toLowerCase().includes(q)).map(d=>d.id),count=ids.filter(id=>ewView.checked.includes(id)).length;workCheck.indeterminate=count>0&&count<ids.length;workCheck.setAttribute('aria-checked',workCheck.indeterminate?'mixed':String(workCheck.checked));}};
render();
